{
    "name": "005_conv_gated_projection_with_causal_conv",
    "hf_id": "LiquidAI/LFM2-1.2B",
    "description": "Complete fused convolution layer operation that combines triple linear projection, element-wise gating, causal 1D grouped convolution, gating with output channel, and final output projection. This is the dominant operation in non-attention layers in LFM2 architecture.",
    "axes": {
        "batch_size": {
            "type": "var",
            "description": "Batch size"
        },
        "seq_len": {
            "type": "var",
            "description": "Sequence length"
        },
        "hidden_size": {
            "type": "const",
            "value": 2048,
            "description": "Hidden dimension size"
        },
        "conv_kernel_size": {
            "type": "const",
            "value": 4,
            "description": "Causal convolution kernel size"
        },
        "triple_hidden": {
            "type": "expr",
            "expression": "hidden_size * 3",
            "description": "Triple projection output dimension"
        }
    },
    "custom_inputs_entrypoint": null,
    "inputs": {
        "x": {
            "shape": [
                "batch_size",
                "seq_len",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Input hidden states"
        },
        "in_proj_weight": {
            "shape": [
                "triple_hidden",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Input projection weight matrix"
        },
        "in_proj_bias": {
            "shape": [
                "triple_hidden"
            ],
            "dtype": "bfloat16",
            "description": "Input projection bias"
        },
        "conv_weight": {
            "shape": [
                "hidden_size",
                "1",
                "conv_kernel_size"
            ],
            "dtype": "bfloat16",
            "description": "Grouped conv1d weight (depthwise)"
        },
        "conv_bias": {
            "shape": [
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Grouped conv1d bias"
        },
        "out_proj_weight": {
            "shape": [
                "hidden_size",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Output projection weight matrix"
        },
        "out_proj_bias": {
            "shape": [
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Output projection bias"
        }
    },
    "outputs": {
        "output": {
            "shape": [
                "batch_size",
                "seq_len",
                "hidden_size"
            ],
            "dtype": "bfloat16",
            "description": "Output hidden states"
        }
    },
    "reference": "import torch\nimport torch.nn.functional as F\n\n@torch.no_grad()\ndef run(\n    x: torch.Tensor,\n    in_proj_weight: torch.Tensor,\n    in_proj_bias: torch.Tensor,\n    conv_weight: torch.Tensor,\n    conv_bias: torch.Tensor,\n    out_proj_weight: torch.Tensor,\n    out_proj_bias: torch.Tensor,\n):\n    \"\"\"\n    Complete fused convolution layer with gated projections and causal convolution.\n    \n    Operation flow:\n    1. Triple linear projection: x -> (B, C, x_proj) via in_proj\n    2. Element-wise gating: Bx = B * x_proj\n    3. Grouped causal 1D convolution on Bx with kernel_size=4\n    4. Output gating: y = C * conv_out\n    5. Final output projection: y -> out_proj(y)\n    \"\"\"\n    batch_size, seq_len, hidden_size = x.shape\n    conv_kernel_size = conv_weight.shape[2]\n    \n    # Step 1: Triple linear projection\n    # Shape: (batch_size, seq_len, 3 * hidden_size)\n    BCx = F.linear(x, in_proj_weight, in_proj_bias)\n    \n    # Transpose for conv1d: (batch_size, 3 * hidden_size, seq_len)\n    BCx = BCx.transpose(-1, -2)\n    \n    # Split into B, C, x_proj along channel dimension\n    # Each has shape: (batch_size, hidden_size, seq_len)\n    B, C, x_proj = BCx.chunk(3, dim=1)\n    \n    # Step 2: Element-wise gating\n    # Shape: (batch_size, hidden_size, seq_len)\n    Bx = B * x_proj\n    \n    # Step 3: Grouped causal 1D convolution\n    # Apply conv with causal padding\n    # Padding is kernel_size - 1 on the left for causal\n    Bx_padded = F.pad(Bx, (conv_kernel_size - 1, 0))\n    \n    # Grouped conv1d with groups=hidden_size (depthwise)\n    conv_out = F.conv1d(Bx_padded, conv_weight, conv_bias, groups=hidden_size)\n    \n    # Shape: (batch_size, hidden_size, seq_len)\n    \n    # Step 4: Output gating with C\n    # Shape: (batch_size, hidden_size, seq_len)\n    y = C * conv_out\n    \n    # Transpose back: (batch_size, seq_len, hidden_size)\n    y = y.transpose(-1, -2).contiguous()\n    \n    # Step 5: Final output projection\n    # Shape: (batch_size, seq_len, hidden_size)\n    output = F.linear(y, out_proj_weight, out_proj_bias)\n    \n    return output\n"
}

